import Foundation

public enum SystemPreference: String, CaseIterable, Identifiable, Sendable { case showFilenameExtensions, showHiddenFiles, dockAutohide, minimizeToApplication; public var id: String { rawValue }; public var explanation: String { switch self { case .showFilenameExtensions: return "Shows file extensions in Finder."; case .showHiddenFiles: return "Shows normally hidden files in Finder."; case .dockAutohide: return "Automatically hides the Dock."; case .minimizeToApplication: return "Keeps minimized windows in their app's Dock icon." } }; fileprivate var domain: String { self == .showHiddenFiles ? "com.apple.finder" : self == .showFilenameExtensions ? "NSGlobalDomain" : "com.apple.dock" }; fileprivate var key: String { switch self { case .showFilenameExtensions: return "AppleShowAllExtensions"; case .showHiddenFiles: return "AppleShowAllFiles"; case .dockAutohide: return "autohide"; case .minimizeToApplication: return "minimize-to-application" } } }
public struct PreferenceService: Sendable { public init() {}; public func isSupported(_ preference: SystemPreference) -> Bool { ProcessInfo.processInfo.operatingSystemVersion.majorVersion >= 13 }; public func value(_ preference: SystemPreference) -> Bool? { UserDefaults.standard.persistentDomain(forName: preference.domain)?[preference.key] as? Bool }; public func set(_ preference: SystemPreference, enabled: Bool) { var domain = UserDefaults.standard.persistentDomain(forName: preference.domain) ?? [:]; domain[preference.key] = enabled; UserDefaults.standard.setPersistentDomain(domain, forName: preference.domain) }; public func reset(_ preference: SystemPreference) { var domain = UserDefaults.standard.persistentDomain(forName: preference.domain) ?? [:]; domain.removeValue(forKey: preference.key); UserDefaults.standard.setPersistentDomain(domain, forName: preference.domain) } }
